func greet(name: String, prefix: String = "Hi") -> String {
    "\(prefix), \(name)!"
}
print(greet(name: "Taylor"))

func doubleNumber(_ x: Int) -> Int {
    x * 2
}
print(doubleNumber(6))

func triple(_ value: inout Int) {
    value *= 3
}
var points = 10
triple(&points)
print(points)

func minMax(a: Int, b: Int) -> (min: Int, max: Int) {
    a < b ? (a, b) : (b, a)
}
let bounds = minMax(a: 8, b: 3)
print(bounds.min)

func square(_ x: Int) -> Int { x * x }
let mathFunc: (Int) -> Int = square
print(mathFunc(5))

func countItems(_ items: String...) -> Int {
    items.count
}
print(countItems("A", "B", "C"))

func makeMultiplier(factor: Int) -> (Int) -> Int {
    func multiply(input: Int) -> Int {
        input * factor
    }
    return multiply
}
let tripleFunc = makeMultiplier(factor: 3)
print(tripleFunc(4))

func register(username: String, at domain: String) -> String {
    "\(username)@\(domain)"
}
print(register(username: "sam", at: "work.com"))

